import type { GuidedLab } from '../../../quizBank';

export const GUIDED: Record<string, GuidedLab> = {"labex-javascript-add-date-by-days-in-javascript":{"intro":"In this lab, we will explore how to add days to a given date in JavaScript. We will create a function that takes in a date and a number of days to add, and returns the resulting date in a string format. We will use the Date constructor and various Date methods to perform the date arithmetic and return the final date.","steps":[{"title":"Add Days to Date","body":["Function to Add Days to a Date","Here's a function that can calculate the date of n days from the given date and return its string representation.","To use the function, follow these steps:","Here's the code for the function:"],"code":[{"lang":"js","text":"const addDaysToDate = (date, n) => {\n  const d = new Date(date);\n  d.setDate(d.getDate() + n);\n  return d.toISOString().split(\"T\")[0];\n};"},{"lang":"js","text":"addDaysToDate(\"2020-10-15\", 10); // '2020-10-25'\naddDaysToDate(\"2020-10-15\", -10); // '2020-10-05'"}]}],"commands":[],"reference":[{"path":"reference.js","text":"addDaysToDate(\"2020-10-15\", 10); // '2020-10-25'\naddDaysToDate(\"2020-10-15\", -10); // '2020-10-05'"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-add-weekdays-to-date":{"intro":"In this lab, we will explore a JavaScript function that helps calculate the date after adding a given number of business days. The function uses array manipulation and date iteration to increment the start date while taking weekends into account. This lab will help you understand how to manipulate dates in JavaScript and apply business logic to date calculations.","steps":[{"title":"Add Weekdays to Date","body":["Function to Add Business Days to a Given Date","To calculate a future date by adding a given number of business days, you can use the addWeekDays function. Here are the steps:","Here are some examples of how you can use the addWeekDays function:"],"code":[{"lang":"js","text":"const addWeekDays = (startDate, count) =>\n  Array.from({ length: count }).reduce((date) => {\n    date = new Date(date.setDate(date.getDate() + 1));\n    if (date.getDay() % 6 === 0)\n      date = new Date(date.setDate(date.getDate() + (date.getDay() / 6 + 1)));\n    return date;\n  }, startDate);"},{"lang":"js","text":"addWeekDays(new Date(\"Oct 09, 2020\"), 5); // 'Oct 16, 2020'\naddWeekDays(new Date(\"Oct 12, 2020\"), 5); // 'Oct 19, 2020'"}]}],"commands":[],"reference":[{"path":"reference.js","text":"addWeekDays(new Date(\"Oct 09, 2020\"), 5); // 'Oct 16, 2020'\naddWeekDays(new Date(\"Oct 12, 2020\"), 5); // 'Oct 19, 2020'"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-test-if-all-array-elements-are-falsy":{"intro":"In this lab, we will explore the concept of testing whether all elements in an array are falsy using JavaScript. We will use the none() function which checks if the provided predicate function returns false for all elements in a collection. Through practical examples, we will see how this function can be used to efficiently manipulate arrays in JavaScript.","steps":[{"title":"Test if All Array Elements Are Falsy","body":["Function to Test if All Array Elements Are Falsy","To test if all elements in an array are falsy, follow these steps:","Here is an example implementation of the function:","You can use the function as follows:"],"code":[{"lang":"js","text":"const none = (arr, fn = Boolean) => !arr.some(fn);"},{"lang":"js","text":"none([0, 1, 3, 0], (x) => x == 2); // true\nnone([0, 0, 0]); // true"}]}],"commands":[],"reference":[{"path":"reference.js","text":"none([0, 1, 3, 0], (x) => x == 2); // true\nnone([0, 0, 0]); // true"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-test-if-all-array-elements-are-truthy":{"intro":"In this lab, we will explore a useful JavaScript function called all. This function tests whether all elements in an array pass a given condition and returns a Boolean value. We will learn how to use this function with different types of arrays and conditions to make our code more efficient and concise.","steps":[{"title":"Test if All Array Elements Are Truthy","body":["Checking if All Array Elements Are True","To check if all elements in a collection are true, you can use the Array.prototype.every() method. This method takes a predicate function as an argument and returns true if the function evaluates to true for all elements in the array.","To simplify the code, you can use a function called all which takes an array and an optional predicate function as arguments. The function uses Array.prototype.every() to check if all elements in the array return true based on the provided function. If no function is provided, Boolean is used as a default.","Here's an example of how to use the all function:"],"code":[{"lang":"js","text":"const all = (arr, fn = Boolean) => arr.every(fn);\n\nall([4, 2, 3], (x) => x > 1); // true\nall([1, 2, 3]); // true"}]}],"commands":[],"reference":[{"path":"reference.js","text":"const all = (arr, fn = Boolean) => arr.every(fn);\n\nall([4, 2, 3], (x) => x > 1); // true\nall([1, 2, 3]); // true"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-javascript-logical-and-operator":{"intro":"Sure, here's an introduction for a JavaScript programming lab on logical AND:","steps":[{"title":"Logical And","body":[],"code":[{"lang":"js","text":"const and = (a, b) => a && b;\nand(true, true); // true\nand(true, false); // false\nand(false, false); // false"}]}],"commands":[],"reference":[{"path":"reference.js","text":"const and = (a, b) => a && b;\nand(true, true); // true\nand(true, false); // false\nand(false, false); // false"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-test-if-any-array-element-is-truthy":{"intro":"In this lab, we will explore how to check if any element in an array is truthy using JavaScript. We will use the Array.prototype.some() method and a provided predicate function to test if at least one element in a collection returns true. Additionally, we will learn how to use the Boolean function as a default argument to simplify the code.","steps":[{"title":"Test if Any Array Element Is Truthy","body":["Testing if Any Array Element is Truthy","To check if any element in a collection returns true based on a provided function, use Array.prototype.some(). If you want to use the Boolean function as default, you may omit the second argument, fn.","You can test it using the following examples:"],"code":[{"lang":"js","text":"const any = (arr, fn = Boolean) => arr.some(fn);"},{"lang":"js","text":"any([0, 1, 2, 0], (x) => x >= 2); // true\nany([0, 0, 1, 0]); // true"}]}],"commands":[],"reference":[{"path":"reference.js","text":"any([0, 1, 2, 0], (x) => x >= 2); // true\nany([0, 0, 1, 0]); // true"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-approximate-number-equality":{"intro":"In this lab, we will explore how to implement a function in JavaScript that checks if two numbers are approximately equal to each other. We will use the Math.abs() method to compare the absolute difference between the two values to a specified or default epsilon value. This lab will help us understand how to handle floating-point numbers with precision in JavaScript.","steps":[{"title":"Approximate Number Equality","body":["Checking for Approximate Number Equality in JavaScript","• Use the Math.abs() method to compare the absolute difference of the two values to epsilon. • If you don't provide a third argument, epsilon, the function will use a default value of 0.001.","To test the function, you can call it with two numbers as arguments, like this:","This will return true because Math.PI / 2.0 is approximately equal to 1.5708 with an epsilon of 0.001."],"code":[{"lang":"js","text":"const approximatelyEqual = (v1, v2, epsilon = 0.001) =>\n  Math.abs(v1 - v2) < epsilon;"},{"lang":"js","text":"approximatelyEqual(Math.PI / 2.0, 1.5708); // true"}]}],"commands":[],"reference":[{"path":"reference.js","text":"approximatelyEqual(Math.PI / 2.0, 1.5708); // true"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-argument-coalescing-in-javascript":{"intro":"In this lab, we will explore the concept of argument coalescing in JavaScript. Argument coalescing is a technique used to return the first defined, non-null argument out of a list of arguments. Through practical examples, we will learn how to implement this technique using JavaScript's built-in methods such as Array.prototype.find() and Array.prototype.includes().","steps":[{"title":"Argument Coalescing","body":["Here's an example of how to use argument coalescing in JavaScript:","In the above code snippet, coalesce is a function that takes any number of arguments and returns the first defined, non-null argument. Here's an example of how to use the coalesce function:","In this example, coalesce is called with a list of arguments that includes null, undefined, an empty string '', NaN, and the string 'Waldo'. The function returns an empty string '' because it is the first defined, non-null argument in the list."],"code":[{"lang":"js","text":"const coalesce = (...args) => args.find((v) => ![undefined, null].includes(v));"},{"lang":"js","text":"coalesce(null, undefined, \"\", NaN, \"Waldo\"); // ''"}]}],"commands":[],"reference":[{"path":"reference.js","text":"coalesce(null, undefined, \"\", NaN, \"Waldo\"); // ''"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-arithmetic-progression-in-javascript":{"intro":"In this lab, we will explore the concept of arithmetic progression in JavaScript. We will learn how to create an array of numbers in the arithmetic progression, starting with a given positive integer and up to a specified limit. By the end of this lab, you will have a solid understanding of how to use the Array.from() and map() methods to create arrays with desired values in the given range.","steps":[{"title":"Arithmetic Progression","body":["Arithmetic Progression Code Example","Here is an example code that creates an array of numbers in arithmetic progression. The array starts with a given positive integer and goes up to a specified limit:","To use this code, simply call the function arithmeticProgression with two arguments: the starting positive integer and the limit. For example:"],"code":[{"lang":"js","text":"const arithmeticProgression = (n, lim) =>\n  Array.from({ length: Math.ceil(lim / n) }, (_, i) => (i + 1) * n);"},{"lang":"js","text":"arithmeticProgression(5, 25); // [5, 10, 15, 20, 25]"}]}],"commands":[],"reference":[{"path":"reference.js","text":"arithmeticProgression(5, 25); // [5, 10, 15, 20, 25]"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-unique-array-difference-calculation":{"intro":"In this lab, we will explore how to calculate the difference between two arrays without filtering duplicate values. The lab will guide you through the process of creating a Set from one array to get the unique values, and then using Array.prototype.filter() on the other array to keep only values that are not contained in the Set. By the end of the lab, you will have a better understanding of how to work with arrays in JavaScript.","steps":[{"title":"Array Difference","body":["To find the difference between two arrays, follow these steps:","• Create a Set from array b to extract the unique values from b.","• Use Array.prototype.filter() on array a to keep only the values that are not in array b, using Set.prototype.has()."],"code":[{"lang":"js","text":"const difference = (a, b) => {\n  const s = new Set(b);\n  return a.filter((x) => !s.has(x));\n};"},{"lang":"js","text":"difference([1, 2, 3, 3], [1, 2, 4]); // Output: [3, 3]"}]}],"commands":[],"reference":[{"path":"reference.js","text":"difference([1, 2, 3, 3], [1, 2, 4]); // Output: [3, 3]"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-check-if-array-elements-are-equal":{"intro":"In this lab, we will be exploring JavaScript programming by implementing a function that checks whether all elements in an array are equal. We will be using the Array.prototype.every() method to compare the elements of the array with the first element and return a boolean value based on whether they are equal or not. This lab is designed to help you get a better understanding of JavaScript arrays and built-in methods.","steps":[{"title":"Check if Array Elements Are Equal","body":["Checking for Equality of Array Elements","To check if all the elements in an array are the same, you can use the Array.prototype.every() method, which compares all elements with the first one.","Here's how you can implement it:","Note that the strict comparison operator is used to compare the elements. This operator doesn't account for NaN self-inequality."],"code":[{"lang":"js","text":"const allEqual = (arr) => arr.every((val) => val === arr[0]);"},{"lang":"js","text":"allEqual([1, 2, 3, 4, 5, 6]); // false\nallEqual([1, 1, 1, 1]); // true"}]}],"commands":[],"reference":[{"path":"reference.js","text":"allEqual([1, 2, 3, 4, 5, 6]); // false\nallEqual([1, 1, 1, 1]); // true"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-check-if-all-array-elements-are-unique":{"intro":"In this lab, we will explore the concept of checking whether all elements in an array are unique using JavaScript. We will use the Set object to eliminate duplicate elements and compare the length of the unique values to the original array. This lab will provide a hands-on experience on how to check for unique elements in an array using JavaScript.","steps":[{"title":"Check if All Array Elements Are Unique","body":["How to Check if All Array Elements Are Unique","To check if all elements in an array are unique, follow these steps:","Here's an example function that implements these steps:","You can use this function to check if an array has all unique elements like this:"],"code":[{"lang":"js","text":"const allUnique = (arr) => arr.length === new Set(arr).size;"},{"lang":"js","text":"allUnique([1, 2, 3, 4]); // true\nallUnique([1, 1, 2, 3]); // false"}]}],"commands":[],"reference":[{"path":"reference.js","text":"allUnique([1, 2, 3, 4]); // true\nallUnique([1, 1, 2, 3]); // false"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-check-if-array-has-duplicates":{"intro":"In this lab, we will explore how to check if an array has duplicates using JavaScript. We will use the Set object to obtain the unique values in the array, then compare the count of these unique values with the length of the original array. By the end of this lab, you will have a better understanding of how to efficiently check for duplicates in an array using JavaScript.","steps":[{"title":"Check if Array Has Duplicates","body":["How to Check for Duplicates in an Array","To check if an array has duplicate values, follow these steps:","Here's an example code snippet that checks for duplicates in an array:","You can test this function with the following code:"],"code":[{"lang":"js","text":"const hasDuplicates = (arr) => new Set(arr).size !== arr.length;"},{"lang":"js","text":"hasDuplicates([0, 1, 1, 2]); // true\nhasDuplicates([0, 1, 2, 3]); // false"}]}],"commands":[],"reference":[{"path":"reference.js","text":"hasDuplicates([0, 1, 1, 2]); // true\nhasDuplicates([0, 1, 2, 3]); // false"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-check-if-array-has-many-matches":{"intro":"In this lab, we will explore the concept of checking if an array has many matches using JavaScript. You will learn how to use the Array.prototype.filter() method in combination with a given function to find all matching array elements and then check if there are more than one such elements using the Array.prototype.length property. By the end of this lab, you will have a better understanding of how to manipulate arrays in JavaScript.","steps":[{"title":"Check if Array Has Many Matches","body":["Function to Check if Array Has Multiple Matches","To check if an array has more than one value matching a given function, follow these steps:"],"code":[{"lang":"js","text":"const hasMany = (arr, fn) => arr.filter(fn).length > 1;"},{"lang":"js","text":"hasMany([1, 3], (x) => x % 2); // true\nhasMany([1, 2], (x) => x % 2); // false"}]}],"commands":[],"reference":[{"path":"reference.js","text":"hasMany([1, 3], (x) => x % 2); // true\nhasMany([1, 2], (x) => x % 2); // false"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-check-if-array-has-only-one-match":{"intro":"In this lab, we will explore the concept of checking if an array has only one match in JavaScript. We will utilize the Array.prototype.filter() method to find all matching array elements and then use the Array.prototype.length property to determine if only one element matches the given function. By the end of the lab, you will have a better understanding of how to effectively check for a single match in an array using JavaScript.","steps":[{"title":"Check if Array Has Only One Match","body":["Function to Check if Array Has Only One Match","To check if an array has only one value matching the given function, follow these steps:"],"code":[{"lang":"js","text":"const hasOne = (arr, fn) => arr.filter(fn).length === 1;"},{"lang":"js","text":"hasOne([1, 2], (x) => x % 2); // true\nhasOne([1, 3], (x) => x % 2); // false"}]}],"commands":[],"reference":[{"path":"reference.js","text":"hasOne([1, 2], (x) => x % 2); // true\nhasOne([1, 3], (x) => x % 2); // false"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-head-of-array":{"intro":"In this lab, we will explore a JavaScript function that returns the head of an array. The function checks if the input array is valid and returns the first element if it exists, otherwise it returns undefined. Through this lab, you will gain a better understanding of array manipulation in JavaScript and learn how to handle edge cases when working with arrays.","steps":[{"title":"Head of Array","body":["How to Get the First Element of an Array in JavaScript","To get the first element of an array in JavaScript, you can use the head function. Here's how you can use it:","• Call the head function with an array as its argument to get the first element. If the array is empty or falsy, the function will return undefined."],"code":[{"lang":"js","text":"const head = (arr) => (arr && arr.length ? arr[0] : undefined);"},{"lang":"js","text":"head([1, 2, 3]); // 1\nhead([]); // undefined\nhead(null); // undefined\nhead(undefined); // undefined"}]}],"commands":[],"reference":[{"path":"reference.js","text":"head([1, 2, 3]); // 1\nhead([]); // undefined\nhead(null); // undefined\nhead(undefined); // undefined"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-check-if-array-includes-all-values":{"intro":"In this lab, we will explore a JavaScript programming exercise that involves checking if all the elements in a given array are included in another array. Through this exercise, you will learn how to use Array.prototype.every() and Array.prototype.includes() to solve this problem efficiently. This lab will help you improve your understanding of JavaScript arrays and array methods.","steps":[{"title":"Check if Array Includes All Values","body":["Function to Check if an Array Includes All Values","If you want to check whether all the elements in an array values are included in another array arr, you can use the includesAll function in JavaScript.","Here's how the includesAll function works:","• It uses Array.prototype.every() and Array.prototype.includes() methods to check if all elements in values are included in arr. • If all elements in values are included in arr, the function will return true. Otherwise, it will return false."],"code":[{"lang":"js","text":"const includesAll = (arr, values) => values.every((v) => arr.includes(v));"},{"lang":"js","text":"includesAll([1, 2, 3, 4], [1, 4]); // true\nincludesAll([1, 2, 3, 4], [1, 5]); // false"}]}],"commands":[],"reference":[{"path":"reference.js","text":"includesAll([1, 2, 3, 4], [1, 4]); // true\nincludesAll([1, 2, 3, 4], [1, 5]); // false"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-check-if-array-includes-any-values":{"intro":"In this lab, we will be exploring a JavaScript function that checks if an array includes any values from another array. We will be using the Array.prototype.some() and Array.prototype.includes() methods to implement the includesAny() function. By the end of this lab, you will have a better understanding of how to efficiently check for the presence of values in arrays using JavaScript.","steps":[{"title":"Check if Array Includes Any Values","body":["Checking if an Array Includes Any Values","To check if an array includes at least one element from another array, use Array.prototype.some() and Array.prototype.includes(). Here is an example function:","You can call this function and pass in the two arrays you want to compare as arguments. The function will return a boolean value indicating whether at least one element of values is included in arr. Here are some examples:"],"code":[{"lang":"js","text":"const includesAny = (arr, values) => values.some((v) => arr.includes(v));"},{"lang":"js","text":"includesAny([1, 2, 3, 4], [2, 9]); // true\nincludesAny([1, 2, 3, 4], [8, 9]); // false"}]}],"commands":[],"reference":[{"path":"reference.js","text":"includesAny([1, 2, 3, 4], [2, 9]); // true\nincludesAny([1, 2, 3, 4], [8, 9]); // false"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-efficient-array-intersection-in-javascript":{"intro":"In this lab, we will explore the concept of array intersection in JavaScript. The main objective of this lab is to help you understand how to find common elements between two arrays while removing any duplicate values. You will learn how to use the Set data structure and the Array.prototype.filter() method to achieve this functionality.","steps":[{"title":"Array Intersection","body":["To find the common elements between two arrays and remove duplicates, use the following code:","This will return an array containing the elements that exist in both arrays, with duplicates removed."],"code":[{"lang":"js","text":"const intersection = (arr1, arr2) => {\n  const set = new Set(arr2);\n  return [...new Set(arr1)].filter((elem) => set.has(elem));\n};"},{"lang":"js","text":"intersection([1, 2, 3], [4, 3, 2]); // [2, 3]"}]}],"commands":[],"reference":[{"path":"reference.js","text":"intersection([1, 2, 3], [4, 3, 2]); // [2, 3]"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-array-is-contained-in-other-array":{"intro":"In this lab, we will explore how to check if one array is contained in another array in JavaScript. We will use various array methods such as for...of, Set, some(), and filter() to write a function that can determine if the elements of the first array are present in the second array, regardless of their order. This lab will help you understand how to manipulate arrays in JavaScript and write efficient code to solve common programming problems.","steps":[{"title":"Array Is Contained in Other Array","body":["Function to Check if an Array is Contained in Another Array","• Use a for...of loop to iterate over a Set created from the first array. • Apply Array.prototype.some() to verify if all distinct values are present in the second array. • Use Array.prototype.filter() to compare the number of occurrences of each distinct value in both arrays. • If the count of any element is greater in the first array than the second one, return false. If not, return true.","Check out the code below to see how it works:","To test the function, use the following code:"],"code":[{"lang":"js","text":"const isContainedIn = (a, b) => {\n  for (const v of new Set(a)) {\n    if (\n      !b.some((e) => e === v) ||\n      a.filter((e) => e === v).length > b.filter((e) => e === v).length\n    )\n      return false;\n  }\n  return true;\n};"},{"lang":"js","text":"isContainedIn([1, 4], [2, 4, 1]); // true"}]}],"commands":[],"reference":[{"path":"reference.js","text":"isContainedIn([1, 4], [2, 4, 1]); // true"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-array-is-sorted":{"intro":"In this lab, we will be working with the isSorted function in JavaScript to determine whether a numeric array is sorted in ascending or descending order. We will use the Math.sign() method to convert the final direction value to -1 for descending order and 1 for ascending order. We will also handle cases where the array is empty, has only one element, or the direction changes for any pair of adjacent array elements.","steps":[{"title":"Array Is Sorted","body":["Code Practice: Check if an Array is Sorted","Here's a function to check if a numeric array is sorted:","To use it, pass an array of numbers to isSorted(). The function will return 1 if the array is sorted in ascending order, -1 if it's sorted in descending order, and 0 if it's not sorted."],"code":[{"lang":"js","text":"const isSorted = (arr) => {\n  if (arr.length <= 1) return 0;\n  const direction = arr[1] - arr[0];\n  for (let i = 2; i < arr.length; i++) {\n    if ((arr[i] - arr[i - 1]) * direction < 0) return 0;\n  }\n  return Math.sign(direction);\n};"},{"lang":"js","text":"isSorted([0, 1, 2, 2]); // 1\nisSorted([4, 3, 2]); // -1\nisSorted([4, 3, 5]); // 0\nisSorted([4]); // 0"}]}],"commands":[],"reference":[{"path":"reference.js","text":"isSorted([0, 1, 2, 2]); // 1\nisSorted([4, 3, 2]); // -1\nisSorted([4, 3, 5]); // 0\nisSorted([4]); // 0"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-recursive-array-permutations-in-javascript":{"intro":"In this lab, we will explore the concept of array permutations in JavaScript. We will learn how to use recursion to generate all possible permutations of an array's elements, even if they contain duplicates. We will also understand how to use Array methods such as map() and reduce() to combine the different permutations into a single array. However, we must keep in mind that executing this function on arrays with more than 8 to 10 elements may significantly increase the execution time and cause the browser to hang.","steps":[{"title":"Array Permutations","body":["How to Generate All Array Permutations","Here's an algorithm that generates all permutations of an array's elements (even if it contains duplicates). Follow these steps to implement it:","• Use recursion. • For each element in the given array, create all the partial permutations for the rest of its elements. • Use Array.prototype.map() to combine the element with each partial permutation, then Array.prototype.reduce() to combine all permutations in one array. • The base cases are for arrays with a length of 2 or 1. • Beware that this function's execution time increases exponentially with each array element. Anything more than 8 to 10 entries may cause your browser to hang as it tries to solve all the different combinations.","You can test the code by calling the permutations() function with an array argument:"],"code":[{"lang":"js","text":"const permutations = (arr) => {\n  if (arr.length <= 2) return arr.length === 2 ? [arr, [arr[1], arr[0]]] : arr;\n  return arr.reduce(\n    (acc, item, i) =>\n      acc.concat(\n        permutations([...arr.slice(0, i), ...arr.slice(i + 1)]).map((val) => [\n          item,\n          ...val\n        ])\n      ),\n    []\n  );\n};"},{"lang":"js","text":"permutations([1, 33, 5]);\n// [ [1, 33, 5], [1, 5, 33], [33, 1, 5], [33, 5, 1], [5, 1, 33], [5, 33, 1] ]"}]}],"commands":[],"reference":[{"path":"reference.js","text":"permutations([1, 33, 5]);\n// [ [1, 33, 5], [1, 5, 33], [33, 1, 5], [33, 5, 1], [5, 1, 33], [5, 33, 1] ]"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-array-ranking-in-javascript":{"intro":"In this lab, we will be exploring the concept of array ranking in JavaScript. The purpose of this lab is to understand how to calculate the ranking of an array based on a comparator function, using techniques such as Array.prototype.map() and Array.prototype.filter(). Through practical examples and exercises, you will gain a better understanding of how to implement this functionality in your own JavaScript projects.","steps":[{"title":"Array Ranking","body":["To use this function, you can:","• Use Array.prototype.map() and Array.prototype.filter() to map each element to a rank using the provided comparator function."],"code":[{"lang":"js","text":"const ranking = (arr, compFn) =>\n  arr.map((a) => arr.filter((b) => compFn(a, b)).length + 1);"},{"lang":"js","text":"ranking([8, 6, 9, 5], (a, b) => a < b);\n// [2, 3, 1, 4]\nranking([\"c\", \"a\", \"b\", \"d\"], (a, b) => a.localeCompare(b) > 0);\n// [3, 1, 2, 4]"}]}],"commands":[],"reference":[{"path":"reference.js","text":"ranking([8, 6, 9, 5], (a, b) => a < b);\n// [2, 3, 1, 4]\nranking([\"c\", \"a\", \"b\", \"d\"], (a, b) => a.localeCompare(b) > 0);\n// [3, 1, 2, 4]"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-random-element-in-array":{"intro":"In this lab, we will explore various JavaScript concepts and apply them to practical programming problems. The purpose of this lab is to help you improve your JavaScript skills by giving you hands-on experience with coding exercises that cover topics such as arrays, objects, loops, functions, and more. By the end of this lab, you will be able to confidently write clean, efficient, and effective JavaScript code.","steps":[{"title":"Random Element in Array","body":["How to Get a Random Element from an Array in JavaScript","To get a random element from an array in JavaScript, follow these steps:","Here's a code snippet that demonstrates this approach:","You can use the getRandomElement function with any array to get a random element. For example:"],"code":[{"lang":"js","text":"const getRandomElement = (arr) => arr[Math.floor(Math.random() * arr.length)];"},{"lang":"js","text":"getRandomElement([3, 7, 9, 11]); // 9"}]}],"commands":[],"reference":[{"path":"reference.js","text":"getRandomElement([3, 7, 9, 11]); // 9"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-array-similarity-algorithm-exploration":{"intro":"In this lab, we will explore the Array Similarity algorithm, which is used to find common elements between two arrays. Through this lab, you will learn how to use built-in JavaScript methods like Array.prototype.includes() and Array.prototype.filter() to compare arrays and extract their common elements. This algorithm is a useful tool for developers when working with large datasets and analyzing data.","steps":[{"title":"Array Similarity","body":["How to Find Array Similarity in JavaScript","• Use the Array.prototype.includes() method to determine the values that are not a part of values. • Use the Array.prototype.filter() method to remove them.","Here's the code to find the array similarity:","You can test this code by running the following command:"],"code":[{"lang":"js","text":"const similarity = (arr, values) => arr.filter((v) => values.includes(v));"},{"lang":"js","text":"similarity([1, 2, 3], [1, 2, 4]); // [1, 2]"}]}],"commands":[],"reference":[{"path":"reference.js","text":"similarity([1, 2, 3], [1, 2, 4]); // [1, 2]"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-array-symmetric-difference":{"intro":"In this lab, we will be exploring the concept of finding the symmetric difference between two arrays in JavaScript. This lab will guide you through the process of creating a Set from each array to get the unique values and using the filter() method to only keep values not contained in the other. By the end of this lab, you will have a solid understanding of how to implement this logic and be able to apply it to your own projects.","steps":[{"title":"Array Symmetric Difference","body":["To find the symmetric difference between two arrays and include duplicate values, follow these steps:","You can use the following examples to test the function:"],"code":[{"lang":"js","text":"const symmetricDifference = (a, b) => {\n  const sA = new Set(a),\n    sB = new Set(b);\n  return [...a.filter((x) => !sB.has(x)), ...b.filter((x) => !sA.has(x))];\n};"},{"lang":"js","text":"symmetricDifference([1, 2, 3], [1, 2, 4]); // [3, 4]\nsymmetricDifference([1, 2, 2], [1, 3, 1]); // [2, 2, 3]"}]}],"commands":[],"reference":[{"path":"reference.js","text":"symmetricDifference([1, 2, 3], [1, 2, 4]); // [3, 4]\nsymmetricDifference([1, 2, 2], [1, 3, 1]); // [2, 2, 3]"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-javascript-fundamentals-through-coding":{"intro":"In this lab, we will explore JavaScript programming concepts and practice implementing them through coding exercises. The lab aims to help beginners gain a deeper understanding of JavaScript syntax, data types, control flow, and functions. By the end of the lab, you will have honed your coding skills and be ready to tackle more complex JavaScript projects.","steps":[{"title":"Array Tail","body":["How to Get Array Tail in JavaScript","To get all the elements in an array except for the first one, you can use the Array.prototype.slice() method. If the array length is more than 1, use slice(1) to return the array without the first element. Otherwise, return the whole array.","While negative slicing (like slice(-4)) is possible in JavaScript and slices from the end, we use slice(1) here because:","• It clearly communicates our intent to skip the first element • It works consistently regardless of array length • Negative slicing would require knowing the array length to get the same result"],"code":[{"lang":"js","text":"const tail = (arr) => (arr.length > 1 ? arr.slice(1) : arr);"},{"lang":"js","text":"tail([1, 2, 3]); // [2, 3]\ntail([1]); // [1]"}]}],"commands":[],"reference":[{"path":"reference.js","text":"tail([1, 2, 3]); // [2, 3]\ntail([1]); // [1]"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-array-to-csv":{"intro":"In this lab, we will explore how to use JavaScript to convert a 2D array to a comma-separated values (CSV) string. The lab will guide you through the process of using Array.prototype.map() and Array.prototype.join() to create a CSV string from a 2D array. By the end of the lab, you will have a solid understanding of how to convert arrays into CSV strings using JavaScript.","steps":[{"title":"Array to CSV","body":["To convert a 2D array to a comma-separated values (CSV) string, follow these steps:","Here is an example of the code:","You can test the function by running the following lines of code:"],"code":[{"lang":"js","text":"const arrayToCSV = (arr, delimiter = \",\") =>\n  arr\n    .map((v) =>\n      v\n        .map((x) => (isNaN(x) ? `\"${x.replace(/\"/g, '\"\"')}\"` : x))\n        .join(delimiter)\n    )\n    .join(\"\\n\");"},{"lang":"js","text":"arrayToCSV([\n  [\"a\", \"b\"],\n  [\"c\", \"d\"]\n]); // '\"a\",\"b\"\\n\"c\",\"d\"'\narrayToCSV(\n  [\n    [\"a\", \"b\"],\n    [\"c\", \"d\"]\n  ],\n  \";\"\n); // '\"a\";\"b\"\\n\"c\";\"d\"'\narrayToCSV([\n  [\"a\", '\"b\" great'],\n  [\"c\", 3.1415]\n]);\n// '\"a\",\"\"\"b\"\" great\"\\n\"c\",3.1415'"}]}],"commands":[],"reference":[{"path":"reference.js","text":"arrayToCSV([\n  [\"a\", \"b\"],\n  [\"c\", \"d\"]\n]); // '\"a\",\"b\"\\n\"c\",\"d\"'\narrayToCSV(\n  [\n    [\"a\", \"b\"],\n    [\"c\", \"d\"]\n  ],\n  \";\"\n); // '\"a\";\"b\"\\n\"c\";\"d\"'\narrayToCSV([\n  [\"a\", '\"b\" great'],\n  [\"c\", 3.1415]\n]);\n// '\"a\",\"\"\"b\"\" great\"\\n\"c\",3.1415'"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-convert-array-to-identity-object":{"intro":"In this lab, we will explore how to convert an array into an identity object using JavaScript. We will be using the Array.prototype.map() method to create an array of key-value pairs, and then we will use the Object.fromEntries() method to convert this array into an object. This lab will help you understand how to manipulate arrays and objects in JavaScript and how to use these methods to create new objects.","steps":[{"title":"Convert Array to Identity Object","body":["Here's how to convert an array to an identity object","• Use Array.prototype.map() to map each value to an array of key-value pairs. • Use Object.fromEntries() to convert the array of key-value pairs into an object."],"code":[{"lang":"js","text":"const toIdentityObject = (arr) => Object.fromEntries(arr.map((v) => [v, v]));"},{"lang":"js","text":"toIdentityObject([\"a\", \"b\"]); // { a: 'a', b: 'b' }"}]}],"commands":[],"reference":[{"path":"reference.js","text":"toIdentityObject([\"a\", \"b\"]); // { a: 'a', b: 'b' }"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-array-to-object-based-on-key":{"intro":"In this lab, we will explore how to convert an array of objects into an object where each object's key is a specified property value of the original objects. We will achieve this by using the Array.prototype.reduce() method and object destructuring in JavaScript. This lab will help you gain a deeper understanding of how to manipulate and transform data in JavaScript.","steps":[{"title":"Array to Object Based on Key","body":["Converting an Array to an Object Based on a Specific Key","To convert an array into an object based on a specific key and exclude that key from each value, follow these steps:","Here's an example implementation:","You can then use the function like this:"],"code":[{"lang":"js","text":"const indexOn = (arr, key) =>\n  arr.reduce((obj, v) => {\n    const { [key]: id, ...data } = v;\n    obj[id] = data;\n    return obj;\n  }, {});"},{"lang":"js","text":"indexOn(\n  [\n    { id: 10, name: \"apple\" },\n    { id: 20, name: \"orange\" }\n  ],\n  \"id\"\n);\n// { '10': { name: 'apple' }, '20': { name: 'orange' } }"}]}],"commands":[],"reference":[{"path":"reference.js","text":"indexOn(\n  [\n    { id: 10, name: \"apple\" },\n    { id: 20, name: \"orange\" }\n  ],\n  \"id\"\n);\n// { '10': { name: 'apple' }, '20': { name: 'orange' } }"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-find-union-of-elements-on-an-array":{"intro":"In this lab, we will dive into the world of JavaScript programming and explore various concepts, including variables, data types, conditional statements, loops, and functions. Through hands-on exercises and projects, you will learn how to write clean and efficient code, debug errors, and create interactive web applications using JavaScript. This lab is designed for beginners who want to develop a strong foundation in JavaScript programming.","steps":[{"title":"Array Union","body":["How to Find the Union of Two Arrays in JavaScript","To find the union of two arrays in JavaScript, follow these steps:","• The union of two arrays returns every element that exists in any of the two arrays at least once.","• To get the union of two arrays, create a Set with all values of a and b, and convert it to an array using the Array.from() method."],"code":[{"lang":"js","text":"const union = (a, b) => Array.from(new Set([...a, ...b]));\n\nconsole.log(union([1, 2, 3], [4, 3, 2])); // Output: [1, 2, 3, 4]"}]}],"commands":[],"reference":[{"path":"reference.js","text":"const union = (a, b) => Array.from(new Set([...a, ...b]));\n\nconsole.log(union([1, 2, 3], [4, 3, 2])); // Output: [1, 2, 3, 4]"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-array-unique-symmetric-difference":{"intro":"In this lab, we will explore the concept of finding unique symmetric difference between two arrays in JavaScript. We will use the Array.prototype.filter() and Array.prototype.includes() methods to remove duplicate values from each array and then create a Set from the results to obtain the final output. This exercise will help to improve your understanding of array manipulation and Set data structure in JavaScript.","steps":[{"title":"Array Unique Symmetric Difference","body":["Array Unique Symmetric Difference Function","To achieve this, use Array.prototype.filter() and Array.prototype.includes() on each array to remove values contained in the other. Create a Set from the results to remove duplicate values.","Use the function as shown below:"],"code":[{"lang":"js","text":"const uniqueSymmetricDifference = (a, b) => [\n  ...new Set([\n    ...a.filter((v) => !b.includes(v)),\n    ...b.filter((v) => !a.includes(v))\n  ])\n];"},{"lang":"js","text":"uniqueSymmetricDifference([1, 2, 3], [1, 2, 4]); // [3, 4]\nuniqueSymmetricDifference([1, 2, 2], [1, 3, 1]); // [2, 3]"}]}],"commands":[],"reference":[{"path":"reference.js","text":"uniqueSymmetricDifference([1, 2, 3], [1, 2, 4]); // [3, 4]\nuniqueSymmetricDifference([1, 2, 2], [1, 3, 1]); // [2, 3]"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-array-without-last-element":{"intro":"In this lab, we will explore how to manipulate arrays in JavaScript by creating a function that returns all the elements of an array except the last one. We will use the Array.prototype.slice() method to achieve this and learn how to slice and extract elements from arrays. This lab will help us understand the fundamentals of working with arrays in JavaScript.","steps":[{"title":"Array Without Last Element","body":["How to Get an Array Without the Last Element","• Use Array.prototype.slice() to return all the elements of the array except the last one."],"code":[{"lang":"js","text":"const initial = (arr) => arr.slice(0, -1);"},{"lang":"js","text":"initial([1, 2, 3]); // [1, 2]"}]}],"commands":[],"reference":[{"path":"reference.js","text":"initial([1, 2, 3]); // [1, 2]"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-check-if-arrays-have-same-contents":{"intro":"In this lab, we will explore how to check if two arrays have the same contents in JavaScript. We will create a function that takes in two arrays and returns true if they contain the same elements, regardless of order, and false otherwise. We will use a combination of Set, for...of loop, and Array.prototype.filter() to achieve this functionality.","steps":[{"title":"Check if Arrays Have Same Contents","body":["Checking for Same Contents in Arrays","To check if two arrays contain the same elements regardless of order, follow these steps:","To test the function, use the following code:"],"code":[{"lang":"js","text":"const haveSameContents = (a, b) => {\n  for (const v of new Set([...a, ...b]))\n    if (a.filter((e) => e === v).length !== b.filter((e) => e === v).length)\n      return false;\n  return true;\n};"},{"lang":"js","text":"haveSameContents([1, 2, 4], [2, 4, 1]); // true"}]}],"commands":[],"reference":[{"path":"reference.js","text":"haveSameContents([1, 2, 4], [2, 4, 1]); // true"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-check-if-two-arrays-intersect":{"intro":"In this lab, we will be exploring an algorithm that determines whether two arrays have a common item or not. We will be using JavaScript and its built-in data structures to create a function that will take two arrays as input and return a boolean value indicating whether they intersect or not. This lab will help you improve your problem-solving skills and enhance your understanding of data structures and algorithms.","steps":[{"title":"Check if Two Arrays Intersect","body":["How to Check if Two Arrays Have a Common Item","To check if two arrays have a common item, follow these steps:","Use the intersects function to check if two arrays intersect:","By following these steps and using the provided code, you can easily check if two arrays have a common item."],"code":[{"lang":"js","text":"const intersects = (a, b) => {\n  const s = new Set(b);\n  return [...new Set(a)].some((x) => s.has(x));\n};"},{"lang":"js","text":"intersects([\"a\", \"b\"], [\"b\", \"c\"]); // true\nintersects([\"a\", \"b\"], [\"c\", \"d\"]); // false"}]}],"commands":[],"reference":[{"path":"reference.js","text":"intersects([\"a\", \"b\"], [\"b\", \"c\"]); // true\nintersects([\"a\", \"b\"], [\"c\", \"d\"]); // false"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-arrays-of-consecutive-elements":{"intro":"In this lab, we will explore how to find all arrays of consecutive elements in a given array using JavaScript. We will learn how to use Array.prototype.slice() and Array.prototype.map() methods to extract and map elements of an array to create arrays of n consecutive elements. This lab will help you improve your understanding of JavaScript array manipulation and functional programming concepts.","steps":[{"title":"Arrays of Consecutive Elements","body":["Finding Arrays of Consecutive Elements","To find arrays of consecutive elements, follow these steps:","Here's an example function that implements these steps:","You can call this function with an array and a number n to find all arrays of n consecutive elements in the array. For example:"],"code":[{"lang":"js","text":"const findConsecutive = (arr, n) =>\n  arr.slice(n - 1).map((v, i) => arr.slice(i, i + n));"},{"lang":"js","text":"findConsecutive([1, 2, 3, 4, 5], 2);\n// [[1, 2], [2, 3], [3, 4], [4, 5]]"}]}],"commands":[],"reference":[{"path":"reference.js","text":"findConsecutive([1, 2, 3, 4, 5], 2);\n// [[1, 2], [2, 3], [3, 4], [4, 5]]"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-assert-object-keys-are-valid":{"intro":"In this lab, we will learn how to validate all the keys in an object and ensure they match a given set of keys. We will make use of the Object.keys() method to get the keys of the object and then use Array.prototype.every() and Array.prototype.includes() to validate each key. This lab will help you to write more efficient and error-free code when working with objects in JavaScript.","steps":[{"title":"Assert Object Keys Are Valid","body":["To ensure that all keys in an object match the specified keys, follow these steps:","Here's an example implementation:","You can use the function like this:"],"code":[{"lang":"js","text":"const validateObjectKeys = (obj, keys) =>\n  Object.keys(obj).every((key) => keys.includes(key));"},{"lang":"js","text":"validateObjectKeys({ id: 10, name: \"apple\" }, [\"id\", \"name\"]); // true\nvalidateObjectKeys({ id: 10, name: \"apple\" }, [\"id\", \"type\"]); // false"}]}],"commands":[],"reference":[{"path":"reference.js","text":"validateObjectKeys({ id: 10, name: \"apple\" }, [\"id\", \"name\"]); // true\nvalidateObjectKeys({ id: 10, name: \"apple\" }, [\"id\", \"type\"]); // false"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-average-of-numbers":{"intro":"In this lab, we will dive into the world of JavaScript programming and explore the concept of calculating the average of numbers. Through hands-on exercises, you will learn how to use the Array.prototype.reduce() method and how to write a function to calculate the average of any number of values. By the end of this lab, you will have a solid understanding of how to use JavaScript to perform mathematical operations on arrays of numbers.","steps":[{"title":"Average of Numbers","body":["How to Calculate the Average of Numbers in JavaScript","To calculate the average of two or more numbers in JavaScript, follow these steps:","Here's an example code snippet you can use:","You can call the average function with an array or multiple arguments:"],"code":[{"lang":"js","text":"const average = (...nums) =>\n  nums.reduce((acc, val) => acc + val, 0) / nums.length;"},{"lang":"js","text":"average(...[1, 2, 3]); // 2\naverage(1, 2, 3); // 2"}]}],"commands":[],"reference":[{"path":"reference.js","text":"average(...[1, 2, 3]); // 2\naverage(1, 2, 3); // 2"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-bifurcate-array-based-on-values":{"intro":"In this lab, we will explore how to bifurcate an array based on given values using JavaScript. The lab will demonstrate how to use the Array.prototype.reduce() method and Array.prototype.push() method to add elements to two groups, based on a given filter. By the end of this lab, you will have a better understanding of how to manipulate arrays in JavaScript.","steps":[{"title":"Bifurcate Array Based on Values","body":["Function to Split Array into Two Groups","To use this function to split an array into two groups based on the values, follow these steps:","Here is the code for the bifurcate() function:","You can call the bifurcate() function with an array of values and a corresponding filter array to split the values into two groups. For example:"],"code":[{"lang":"js","text":"const bifurcate = (arr, filter) =>\n  arr.reduce(\n    (acc, val, i) => (acc[filter[i] ? 0 : 1].push(val), acc),\n    [[], []]\n  );"},{"lang":"js","text":"bifurcate([\"beep\", \"boop\", \"foo\", \"bar\"], [true, true, false, true]);\n// [ ['beep', 'boop', 'bar'], ['foo'] ]"}]}],"commands":[],"reference":[{"path":"reference.js","text":"bifurcate([\"beep\", \"boop\", \"foo\", \"bar\"], [true, true, false, true]);\n// [ ['beep', 'boop', 'bar'], ['foo'] ]"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-binary-search-in-javascript":{"intro":"In this lab, you will learn the fundamentals of JavaScript programming, including variables, data types, functions, and control flow, and practice implementing the binary search algorithm.","steps":[{"title":"Binary Search","body":["• Declare the left and right search boundaries, l and r, initialized to 0 and the length of the array respectively. • Use a while loop to repeatedly narrow down the search subarray by dividing it in half using Math.floor(). • If the element is found, return its index. Otherwise, return -1. • Note that this algorithm does not account for duplicate values in the array.","Here's an example implementation of the binary search algorithm in JavaScript:","You can test the binarySearch function with the following examples:"],"code":[{"lang":"js","text":"const binarySearch = (arr, item) => {\n  let l = 0,\n    r = arr.length - 1;\n  while (l <= r) {\n    const mid = Math.floor((l + r) / 2);\n    const guess = arr[mid];\n    if (guess === item) return mid;\n    if (guess > item) r = mid - 1;\n    else l = mid + 1;\n  }\n  return -1;\n};"},{"lang":"js","text":"binarySearch([1, 2, 3, 4, 5], 1); // 0\nbinarySearch([1, 2, 3, 4, 5], 5); // 4\nbinarySearch([1, 2, 3, 4, 5], 6); // -1"}]}],"commands":[],"reference":[{"path":"reference.js","text":"binarySearch([1, 2, 3, 4, 5], 1); // 0\nbinarySearch([1, 2, 3, 4, 5], 5); // 4\nbinarySearch([1, 2, 3, 4, 5], 6); // -1"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"}};
